<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>KITA Password Setup</title><style>body{margin:0;background:#f5f8ff;font:15px system-ui;color:#172b55;display:grid;min-height:100vh;place-items:center}main{background:white;border:1px solid #dbe5fa;border-radius:16px;padding:28px;width:min(420px,85vw)}label{display:block;margin:16px 0 5px}input,button{box-sizing:border-box;width:100%;padding:12px;border:1px solid #ccd9f2;border-radius:8px}button{margin-top:14px;background:#2056ec;color:white;cursor:pointer}a{color:#2056ec}#message{line-height:1.5}</style></head><body><main><h1>{{ $setup ? 'Set Your Password' : 'Account Recovery' }}</h1><p>{{ $setup ? 'Set a personal password before accessing KITA.' : 'Use your registered email to recover access.' }}</p><form id="form">@csrf
@if($setup)<label for="current_password">Temporary Password</label><input id="current_password" name="current_password" type="password" autocomplete="current-password" required>
@else<label for="email">Registered Email</label><input id="email" name="email" type="email" autocomplete="email" required><button type="button" data-action="/password/resend">Resend Setup Credentials</button><button type="button" data-action="/password/code">Send Password Reset OTP</button><label for="otp">Email OTP</label><input id="otp" name="otp" inputmode="numeric" pattern="[0-9]{6}" autocomplete="one-time-code" required><button type="button" id="verify">Verify OTP</button>@endif
<div id="new-password" @if(!$setup) hidden @endif><label for="password">New Password</label><input id="password" name="password" type="password" autocomplete="new-password" minlength="12" maxlength="255" required><label for="password_confirmation">Confirm New Password</label><input id="password_confirmation" name="password_confirmation" type="password" autocomplete="new-password" minlength="12" maxlength="255" required><p>Use at least 12 characters. A long passphrase works well.</p><button type="submit">{{ $setup ? 'Save Password' : 'Save Password' }}</button></div></form><p id="message" role="status" aria-live="polite"></p>@if($setup)<button id="logout">Log Out</button>@else<a href="/">Back to Login</a>@endif</main><script>
const form=document.getElementById('form'),message=document.getElementById('message');let busy=false;
async function send(url,data){if(busy)return;busy=true;document.querySelectorAll('button').forEach(b=>b.disabled=true);try{const r=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':form.elements._token.value},body:JSON.stringify(data)});const body=await r.json();message.textContent=body.message||'Please try again.';if(r.ok&&body.verified){document.getElementById('new-password').hidden=false;document.getElementById('email').readOnly=true;}if(r.ok&&body.redirect)window.location.assign(body.redirect);}catch(e){message.textContent='Unable to complete the request. Please try again.';}finally{busy=false;document.querySelectorAll('button').forEach(b=>b.disabled=false);}}
document.getElementById('verify')?.addEventListener('click',()=>send('/password/verify',{email:form.elements.email.value,otp:form.elements.otp.value}));
form.addEventListener('submit',e=>{e.preventDefault();send(@json($setup ? '/password/setup' : '/password/recovery'),Object.fromEntries(new FormData(form)));});document.querySelectorAll('[data-action]').forEach(b=>b.addEventListener('click',()=>{if(form.elements.email.reportValidity())send(b.dataset.action,{email:form.elements.email.value});}));document.getElementById('logout')?.addEventListener('click',async()=>{await send('/logout',{});window.location.assign('/');});
</script></body></html>